 "content": "def transform(grid):
    # Adjacent repeated rows and columns encode duplicated cells; keep one of each.
    rows = []
    for row in grid:
        row = list(row)
        if not rows or row != rows[-1]:
            rows.append(row)
    if not rows:
        return []

    out = []
    previous_column = None
    for c in range(len(rows[0])):
        column = tuple(row[c] for row in rows)
        if column != previous_column:
            for r, value in enumerate(column):
                if len(out) <= r:
                    out.append([])
                out[r].append(value)
            previous_column = column
    return out

